1	//! A journal of foreground work and the semantic boundaries between activity intervals.
2	//!
3	//! The foreground thread records task polls, action handlers, input dispatches,
4	//! draws, and presentations as [`ForegroundEvent`]s in a bounded journal ring.
5	//! Task polls shorter than [`TASK_POLL_FLOOR`] are folded into summaries, which
6	//! bound the stream by the number of slow polls while preserving their exact
7	//! count and total duration.
8	//!
9	//! Presentation and the foreground going idle are explicit [`IntervalBoundary`]
10	//! entries in the same stream. Independent [`ForegroundJournalCollector`]s
11	//! feed entries to [`IntervalSealer`], a pure state machine that groups all work
12	//! preceding each boundary into a [`FrameSnapshot`]. The sealer does not infer
13	//! boundaries from elapsed time or from incidental event kinds such as draws.
14	
15	use std::cell::{RefCell, UnsafeCell};
16	use std::collections::{HashMap, VecDeque};
17	use std::mem::MaybeUninit;
18	use std::sync::{
19	    Arc,
20	    atomic::{AtomicU64, AtomicUsize, Ordering},
21	};
22	use std::time::Duration;
23	
24	use scheduler::Instant;
25	
26	use super::{ActionTiming, FrameTiming, PresentTiming, TaskTiming};
27	use crate::WindowId;
28	
29	/// Task polls shorter than this are folded into a [`PollSummary`] instead of
30	/// being recorded individually. This keeps the stream bounded by the number
31	/// of *slow* polls while preserving their exact count and total duration.
32	pub const TASK_POLL_FLOOR: Duration = Duration::from_micros(100);
33	
34	/// A dirty frame that has not been presented by this deadline stops blocking
35	/// foreground-idle boundaries, so a window that never presents (hidden or
36	/// occluded windows receive no frame callbacks) cannot suppress boundaries
37	/// indefinitely. Expiry only unblocks: the open interval still seals at a
38	/// real presentation or idle boundary, keeping a starving hang and the frame
39	/// it starved in one interval.
40	pub const FRAME_DEADLINE: Duration = Duration::from_secs(1);
41	
42	// Backstop against pathological event storms within a single interval. At the
43	// 100us floor, a fully hung second can produce at most ~10k recordable polls,
44	// so this bound is only reachable when something is already deeply wrong.
45	const MAX_INTERVAL_EVENTS: usize = 16 * 1024;
46	
47	// Allow 4MiB for the fixed ring allocation, including each slot's atomic
48	// metadata. The poll floor and frame cadence bound the event rate to roughly
49	// 10k per second in the worst case, so this holds several seconds of
50	// worst-case traffic between consumer drains.
51	const MAX_JOURNAL_ENTRIES: usize = (4 * 1024 * 1024) / core::mem::size_of::<JournalSlot>();
52	
53	// Absorbs brief collisions with a collector reading the exact slot being
54	// wrapped. The foreground never waits for a reader; queued entries are retried
55	// in order on the next publication.
56	const MAX_PENDING_JOURNAL_ENTRIES: usize = 64;
57	
58	/// One entry in the foreground stream.
59	///
60	/// Events are recorded in completion order (ordered by their end time). An
61	/// event that was in progress across a frame boundary (e.g. the task poll
62	/// enclosing a draw) is recorded when it *ends*, with timestamps that may
63	/// precede events recorded before it.
64	#[derive(Debug, Copy, Clone)]
65	pub enum ForegroundEvent {
66	    /// A foreground task poll at least [`TASK_POLL_FLOOR`] long.
67	    TaskPoll(TaskTiming),
68	    /// A completed action handler.
69	    Action(ActionTiming),
70	    /// A dispatched platform input event.
71	    Input(InputTiming),
72	    /// A completed window draw.
73	    Draw(FrameTiming),
74	    /// Work spent submitting a frame to the platform.
75	    Present(PresentTiming),
76	    /// Aggregate of task polls below [`TASK_POLL_FLOOR`], flushed before the
77	    /// next individually retained event or interval boundary.
78	    SmallPolls(SmallPollFlush),
79	}
80	
81	impl ForegroundEvent {
82	    /// When the work described by this event began. For draws this is the
83	    /// start of the draw itself, not the frame's first invalidation.
84	    pub fn start_time(&self) -> Instant {
85	        match self {
86	            Self::TaskPoll(timing) => timing.start,
87	            Self::Action(timing) => timing.start,
88	            Self::Input(timing) => timing.start,
89	            Self::Draw(timing) => timing.draw_start,
90	            Self::Present(timing) => timing.present_start,
91	            Self::SmallPolls(flush) => flush.since,
92	        }
93	    }
94	
95	    /// When the work described by this event ended.
96	    pub fn end_time(&self) -> Instant {
97	        match self {
98	            Self::TaskPoll(timing) => timing.end.0,
99	            Self::Action(timing) => timing.end,
100	            Self::Input(timing) => timing.end,
101	            Self::Draw(timing) => timing.draw_end,
102	            Self::Present(timing) => timing.present_end,
103	            Self::SmallPolls(flush) => flush.until,
104	        }
105	    }
106	
107	    /// How long the work described by this event took. For
108	    /// [`Self::SmallPolls`] this is the span the summary covers, not time
109	    /// spent polling; use the summary's `total` for occupancy.
110	    pub fn duration(&self) -> Duration {
111	        self.end_time().duration_since(self.start_time())
112	    }
113	}
114	
115	/// Timing of one platform input dispatch on a window.
116	#[derive(Debug, Copy, Clone)]
117	pub struct InputTiming {
118	    /// The platform input variant dispatched (see
119	    /// [`crate::PlatformInput::kind_name`]).
120	    pub kind: &'static str,
121	    /// When the input dispatch started.
122	    pub start: Instant,
123	    /// When the input dispatch finished.
124	    pub end: Instant,
125	    /// Whether handling the input invalidated a window.
126	    pub caused_invalidation: bool,
127	}
128	
129	/// Exact count and total duration of task polls below [`TASK_POLL_FLOOR`].
130	#[derive(Debug, Copy, Clone, Default, PartialEq, Eq)]
131	pub struct PollSummary {
132	    /// Number of polls below the floor.
133	    pub count: u64,
134	    /// Total duration of polls below the floor.
135	    pub total: Duration,
136	}
137	
138	impl PollSummary {
139	    fn add(&mut self, other: Self) {
140	        self.count += other.count;
141	        self.total += other.total;
142	    }
143	}
144	
145	/// A flushed [`PollSummary`] and the tightest span containing its folded polls.
146	#[derive(Debug, Copy, Clone)]
147	pub struct SmallPollFlush {
148	    /// The folded polls.
149	    pub summary: PollSummary,
150	    /// When the first folded poll began.
151	    pub since: Instant,
152	    /// When the last folded poll ended.
153	    pub until: Instant,
154	}
155	
156	/// A newly drawn frame and the platform submission that completed its interval.
157	#[derive(Debug, Copy, Clone)]
158	pub struct PresentedFrame {
159	    /// The draw whose rendered scene was submitted.
160	    pub frame: FrameTiming,
161	    /// Work spent submitting that scene to the platform.
162	    pub presentation: PresentTiming,
163	}
164	
165	impl PresentedFrame {
166	    /// Time from the frame's first invalidation through platform submission.
167	    pub fn dirty_to_present_duration(&self) -> Option<Duration> {
168	        self.frame
169	            .dirty_at
170	            .map(|dirty_at| self.presentation.present_end.duration_since(dirty_at))
171	    }
172	}
173	
174	/// The semantic event that completed a foreground activity interval.
175	#[derive(Debug, Copy, Clone)]
176	pub enum IntervalBoundary {
177	    /// A newly drawn frame was submitted to the platform.
178	    Presented(PresentedFrame),
179	    /// The foreground returned to an idle platform loop with no unexpired
180	    /// frame pending.
181	    Idle {
182	        /// When the foreground went idle.
183	        ended_at: Instant,
184	    },
185	}
186	
187	impl IntervalBoundary {
188	    /// When the interval ended.
189	    pub fn end_time(&self) -> Instant {
190	        match self {
191	            Self::Presented(presented) => presented.presentation.present_end,
192	            Self::Idle { ended_at } => *ended_at,
193	        }
194	    }
195	
196	    /// The first invalidation of the frame satisfied by this boundary, if any.
197	    pub fn dirty_at(&self) -> Option<Instant> {
198	        match self {
199	            Self::Presented(presented) => presented.frame.dirty_at,
200	            Self::Idle { .. } => None,
201	        }
202	    }
203	}
204	
205	/// A control-plane change to one window's pending-frame state.
206	#[derive(Debug, Copy, Clone)]
207	pub enum FrameStateChange {
208	    /// The window has a frame waiting to be presented.
209	    Pending {
210	        /// The window waiting for presentation.
211	        window_id: WindowId,
212	        /// When this frame generation first became dirty.
213	        dirty_at: Instant,
214	    },
