391	impl ForegroundJournalWriter {
392	    fn new(foreground_runnables: ForegroundRunnableCounter, publisher: JournalPublisher) -> Self {
393	        Self {
394	            foreground_runnables,
395	            publisher,
396	            turn_depth: 0,
397	            pending_frames: HashMap::new(),
398	            retained_since_boundary: false,
399	            small_polls: None,
400	        }
401	    }
402	
403	    fn begin_turn(&mut self) {
404	        self.turn_depth += 1;
405	    }
406	
407	    // Idle boundaries require a retained event since the last boundary, not
408	    // merely folded sub-floor polls. Sporadic wake-ups (timers, file
409	    // watchers) leave the foreground idle after every tiny poll; a boundary
410	    // for each would re-admit to the ring the very polls the fold keeps out
411	    // of it, wrapping the ring within seconds. Folded-only work is discarded
412	    // at true idle so unrelated wake-ups cannot accumulate toward a later
413	    // frame budget. Polls remain folded while a frame or runnable is pending.
414	    fn end_turn(&mut self, ended_at: Instant) {
415	        let Some(turn_depth) = self.turn_depth.checked_sub(1) else {
416	            debug_assert!(false, "foreground turn must be begun before it ends");
417	            return;
418	        };
419	        self.turn_depth = turn_depth;
420	        if self.turn_depth > 0
421	            || self.foreground_runnables.has_runnables()
422	            || self.has_unexpired_pending_frame(ended_at)
423	        {
424	            return;
425	        }
426	        if !self.retained_since_boundary {
427	            self.small_polls = None;
428	            return;
429	        }
430	
431	        self.record_entry(ForegroundJournalEntry::Boundary(IntervalBoundary::Idle {
432	            ended_at,
433	        }));
434	    }
435	
436	    fn has_unexpired_pending_frame(&mut self, now: Instant) -> bool {
437	        if self.pending_frames.is_empty() {
438	            return false;
439	        }
440	        self.pending_frames
441	            .retain(|_, dirty_at| now.saturating_duration_since(*dirty_at) < FRAME_DEADLINE);
442	        !self.pending_frames.is_empty()
443	    }
444	
445	    fn fold_small_poll(&mut self, timing: TaskTiming) {
446	        let flush = self.small_polls.get_or_insert(SmallPollFlush {
447	            summary: PollSummary::default(),
448	            since: timing.start,
449	            until: timing.end.0,
450	        });
451	        flush.summary.count += 1;
452	        flush.summary.total += timing.poll_duration();
453	        flush.since = flush.since.min(timing.start);
454	        flush.until = flush.until.max(timing.end.0);
455	    }
456	
457	    fn take_small_polls(&mut self) -> Option<SmallPollFlush> {
458	        self.small_polls.take()
459	    }
460	
461	    fn record_event(&mut self, event: ForegroundEvent) {
462	        self.retained_since_boundary = true;
463	        self.record_entry(ForegroundJournalEntry::Event(event));
464	    }
465	
466	    fn record_entry(&mut self, entry: ForegroundJournalEntry) {
467	        let small_polls = self
468	            .take_small_polls()
469	            .map(ForegroundEvent::SmallPolls)
470	            .map(ForegroundJournalEntry::Event);
471	        self.publisher
472	            .publish([small_polls, Some(entry)].into_iter().flatten());
473	        if matches!(entry, ForegroundJournalEntry::Boundary(_)) {
474	            self.retained_since_boundary = false;
475	        }
476	    }
477	
478	    fn record_frame_state(&mut self, change: FrameStateChange) {
479	        self.record_entry(ForegroundJournalEntry::FrameState(change));
480	    }
481	
482	    fn record_frame_pending(&mut self, window_id: WindowId, dirty_at: Instant) {
483	        let should_record = match self.pending_frames.get(&window_id) {
484	            Some(previous_dirty_at) => {
485	                dirty_at.saturating_duration_since(*previous_dirty_at) >= FRAME_DEADLINE
486	            }
487	            None => true,
488	        };
489	        if !should_record {
490	            return;
491	        }
492	
493	        self.pending_frames.insert(window_id, dirty_at);
494	        self.record_frame_state(FrameStateChange::Pending {
495	            window_id,
496	            dirty_at,
497	        });
498	    }
499	
500	    fn record_window_closed(&mut self, window_id: WindowId, at: Instant) {
501	        self.pending_frames.remove(&window_id);
502	        self.record_frame_state(FrameStateChange::Closed { window_id, at });
503	    }
504	
505	    fn record_present(&mut self, timing: PresentTiming, frame: Option<FrameTiming>) {
506	        match frame {
507	            Some(frame) => {
508	                self.pending_frames.remove(&frame.window_id);
509	                self.record_entry(ForegroundJournalEntry::Boundary(
510	                    IntervalBoundary::Presented(PresentedFrame {
511	                        frame,
512	                        presentation: timing,
513	                    }),
514	                ));
515	            }
516	            None => {
517	                self.pending_frames.remove(&timing.window_id);
518	                self.record_event(ForegroundEvent::Present(timing));
519	            }
520	        }
521	    }
