fn present(&mut self) {
    #[cfg(feature = "profiler")]
    let _foreground_turn = profiler::journal::foreground_turn();
    #[cfg(feature = "profiler")]
    let present_start = Instant::now();
    self.platform_window.draw(&self.rendered_frame.scene);
